-- Local candidate only. Remote project identity and authorization require a separate gate.
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL search_path=pg_catalog,pg_temp;
SET LOCAL statement_timeout='45s';
SET LOCAL lock_timeout='2s';
DO $$ BEGIN IF current_database()<>'postgres' OR current_user<>'postgres' OR (SELECT array_agg(signature) FROM artecna_distruzione.hard_delete_catalog_expected) IS DISTINCT FROM ARRAY[artecna_distruzione.hard_delete_catalog()] THEN RAISE EXCEPTION 'STOP_IDENTITA_O_HARD_DELETE';END IF;END $$;
DO $$ DECLARE f text;obj oid;BEGIN FOREACH f IN ARRAY ARRAY['public.anteprima_bluenext_integrata(jsonb)','public.conferma_bluenext_integrato(uuid,jsonb,jsonb,text,boolean,boolean)','public.leggi_esito_bluenext_integrato(uuid)','public.leggi_fonte_bluenext(uuid,text)','public.elenca_fonti_bluenext(uuid)'] LOOP obj:=to_regprocedure(f);IF obj IS NULL OR NOT has_function_privilege('authenticated',obj,'EXECUTE') OR has_function_privilege('anon',obj,'EXECUTE') OR has_function_privilege('service_role',obj,'EXECUTE') OR NOT EXISTS(SELECT FROM pg_proc WHERE oid=obj AND prosecdef AND pg_get_userbyid(proowner)='postgres' AND proconfig=ARRAY['search_path=pg_catalog, pg_temp']) THEN RAISE EXCEPTION 'STOP_FUNZIONE_O_ACL';END IF;END LOOP;IF (SELECT count(*) FROM pg_class WHERE oid IN('artecna_contabilita.bluenext_fonti'::regclass,'artecna_contabilita.bluenext_evidenze'::regclass,'artecna_contabilita.bluenext_lotti'::regclass) AND relrowsecurity)<>3 OR EXISTS(SELECT FROM pg_policies WHERE schemaname='artecna_contabilita' AND tablename IN('bluenext_fonti','bluenext_evidenze','bluenext_lotti')) THEN RAISE EXCEPTION 'STOP_RLS_FONTI'; END IF;END $$;
-- Exact canonical-LF function bodies, owner, volatility, security and search_path.
DO $seal$ BEGIN IF EXISTS(SELECT FROM (VALUES
('artecna_contabilita.pulisci_fonti_bluenext()','ea3efe9015bedf439ce671dee3c9f829c297a15cc5acb9da80a7aef6a23abb89',true,'v'),
('artecna_contabilita.xml_originale_bluenext(uuid)','cb35ecfeb6155968f0a8e86f3fb16120d7cd0f127c0ad20e6fd015b5d6a55acd',true,'s'),
('artecna_contabilita.documento_riconciliazione(uuid,jsonb)','95114bc3058f2a7a6255a324322591d43756d50579ce12ae52b9174ecb48197a',true,'s'),
('artecna_contabilita.esamina_ricevuta_bluenext(jsonb)','8eb2e26ce36bd846db55be670ec1c1cb8a8711dbeab1f50f119b0374f0b9baa1',false,'s'),
('public.anteprima_bluenext_integrata(jsonb)','f20419a2f52b4d52006d8edebcea68371bd17d769255f8acfbade9d6062695f5',true,'s'),
('public.leggi_esito_bluenext_integrato(uuid)','685552843c399d6de7c49d3044596f4ee64537a36f5f461d082091cf2282e3c7',true,'s'),
('public.conferma_bluenext_integrato(uuid,jsonb,jsonb,text,boolean,boolean)','4231d8971f347fc26169b20a12078a4bbc9052d6d821fabe8641be7a626b5b7e',true,'v'),
('public.leggi_fonte_bluenext(uuid,text)','837947135d063eced671afa919db551263243434ebe4685a0556583409f6f7e2',true,'s'),
('public.elenca_fonti_bluenext(uuid)','0d3859a254b3bfd1a1eba5dcc81becd67ced3f5691dfe2c16dc605d92f826d82',true,'s')
) AS expected(signature,digest,definer,volatility) LEFT JOIN pg_proc p ON p.oid=to_regprocedure(expected.signature) WHERE p.oid IS NULL OR encode(sha256(convert_to(replace(p.prosrc,E'\r\n',E'\n'),'UTF8')),'hex')<>expected.digest OR pg_get_userbyid(p.proowner)<>'postgres' OR p.prosecdef<>expected.definer OR p.provolatile::text<>expected.volatility OR p.proconfig IS DISTINCT FROM ARRAY['search_path=pg_catalog, pg_temp']) THEN RAISE EXCEPTION 'STOP_DEFINIZIONI_SIGILLATE';END IF;
IF EXISTS(SELECT FROM pg_class c CROSS JOIN (VALUES('anon'),('authenticated'),('service_role')) AS roles(name) WHERE c.oid IN('artecna_contabilita.bluenext_fonti'::regclass,'artecna_contabilita.bluenext_evidenze'::regclass,'artecna_contabilita.bluenext_lotti'::regclass) AND has_table_privilege(roles.name,c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')) THEN RAISE EXCEPTION 'STOP_ACL_TABELLE_PRIVATE';END IF;END $seal$;
WITH rel AS(SELECT unnest(ARRAY['public.cantieri','public.preventivi_cantiere','public.sal_lavorazioni','public.acconti_cantiere','public.fatture_emesse','public.fatture_fornitori','public.fatture_fornitori_righe','public.utenti_impresa','public.utenti_cantiere','artecna_contabilita.attribuzioni_clienti','artecna_contabilita.incassi_lordi_clienti','artecna_contabilita.quote_lorde_clienti','artecna_contabilita.imputazioni_acconti','artecna_contabilita.acconti_fiscali','artecna_contabilita.fatture_sdi','artecna_contabilita.storni_acconti','artecna_notifiche.evento_notificabile','artecna_notifiche.notifica']) AS name), digests AS (SELECT name,query_to_xml(format('SELECT count(*) AS rows,encode(sha256(convert_to(coalesce(string_agg((CASE WHEN %L=''public.fatture_emesse'' THEN to_jsonb(t)||jsonb_build_object(''xml_testo'',coalesce(to_jsonb(t)->''xml_testo'',''null''::jsonb)) ELSE to_jsonb(t) END)::text,E''\n'' ORDER BY to_jsonb(t)::text COLLATE "C"),''''),''UTF8'')),''hex'') AS sha256 FROM %s t',name,name::regclass),false,false,'') AS value FROM rel) SELECT jsonb_build_object('marker','ARTECNA_BLUENEXT_INTEGRATO_POSTCHECK_READONLY','readonly',current_setting('transaction_read_only'),'fingerprints',jsonb_object_agg(name,jsonb_build_object('rows',(xpath('/table/row/rows/text()',value))[1]::text::bigint,'sha256',(xpath('/table/row/sha256/text()',value))[1]::text)),'migration_registry_modified',false,'rollback_proven_by_row',false) AS evidence FROM digests;
ROLLBACK;
